    def minimumBoxes(self, n: int) -> int:
        layers = 0
        while (layers + 1) * (layers + 2) * (layers + 3) // 6 <= n:
            layers += 1
        rem = n - layers * (layers + 1) * (layers + 2) // 6
        diag = 0
        while (diag + 1) * (diag + 2) // 2 <= rem:
            diag += 1
        base = layers * (layers + 1) // 2 + diag
        if rem - diag * (diag + 1) // 2 > 0:
            base += 1
        return base

