class Solution:
    def minimumBoxes(self, n: int) -> int:
        tetra = lambda x: x * (x + 1) * (x + 2) // 6
        tri = lambda x: x * (x + 1) // 2

        def max_with(f, hi, cap):
            lo = 0
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if f(mid) <= cap:
                    lo = mid
                else:
                    hi = mid - 1
            return lo

        layers = max_with(tetra, 2000, n)
        rem = n - tetra(layers)
        diag = max_with(tri, 50000, rem)
        return tri(layers) + diag + (1 if rem - tri(diag) > 0 else 0)

