class Solution {
public:
    int minimumBoxes(int n) {
        auto tetra = [](long long x) { return x * (x + 1) * (x + 2) / 6; };
        auto tri = [](long long x) { return x * (x + 1) / 2; };
        long long lo = 0, hi = 2000;
        while (lo < hi) {
            long long mid = (lo + hi + 1) / 2;
            if (tetra(mid) <= n) lo = mid; else hi = mid - 1;
        }
        long long layers = lo, rem = n - tetra(layers);
        lo = 0; hi = 50000;
        while (lo < hi) {
            long long mid = (lo + hi + 1) / 2;
            if (tri(mid) <= rem) lo = mid; else hi = mid - 1;
        }
        long long base = tri(layers) + lo;
        if (rem - tri(lo) > 0) base++;
        return (int)base;
    }
};

