var minimumBoxes = function(n) {
    const tetra = (x) => x * (x + 1) * (x + 2) / 6;
    const tri = (x) => x * (x + 1) / 2;
    let lo = 0, hi = 2000;
    while (lo < hi) {
        const mid = Math.floor((lo + hi + 1) / 2);
        if (tetra(mid) <= n) lo = mid; else hi = mid - 1;
    }
    const layers = lo;
    const rem = n - tetra(layers);
    lo = 0; hi = 50000;
    while (lo < hi) {
        const mid = Math.floor((lo + hi + 1) / 2);
        if (tri(mid) <= rem) lo = mid; else hi = mid - 1;
    }
    return tri(layers) + lo + (rem - tri(lo) > 0 ? 1 : 0);
};
